@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-separator {
    flex-shrink: 0;
    align-self: stretch;
    margin: 0;
    border: 0 solid var(--nz-separator-color, var(--nz-border-subtle));
    border-block-start-width: var(--nz-border-width-default);
  }

  .nz-separator[data-orientation='vertical'] {
    border-block-start-width: 0;
    border-inline-start-width: var(--nz-border-width-default);
  }

  @media (forced-colors: active) {
    .nz-separator {
      border-color: CanvasText;
    }
  }
}
